import{assert}from"chrome://resources/js/assert.js";import{getTemplate}from"./base_setup_page.html.js";export const NEXT_PAGE_EVENT="next-page";export const CANCEL_SETUP_EVENT="cancel-setup";export class BaseSetupPageElement extends HTMLElement{static get observedAttributes(){return["page-number","total-pages"]}constructor(){super();const template=document.createElement("template");template.innerHTML=getTemplate();this.attachShadow({mode:"open"}).appendChild(template.content.cloneNode(true))}connectedCallback(){const contentElement=this.shadowRoot.querySelector("#content");this.updateContentFade(contentElement);contentElement.addEventListener("scroll",this.updateContentFade.bind(undefined,contentElement),{passive:true});this.shadowRoot.querySelector("#dialog").focus()}attributeChangedCallback(name,_oldValue,_newValue){assert(name==="page-number"||name==="total-pages");const dotsElement=this.shadowRoot?.querySelector("#dots");assert(window.trustedTypes);dotsElement.innerHTML=window.trustedTypes.emptyHTML;const pages=parseInt(this.getAttribute("total-pages"))||0;const curPage=parseInt(this.getAttribute("page-number"))||0;for(let i=0;i<pages;i++){const dot=document.createElement("div");if(i===curPage){dot.classList.add("active")}dotsElement.appendChild(dot)}}updateContentFade(contentElement){window.requestAnimationFrame((()=>{const atTop=contentElement.scrollTop===0;const atBottom=contentElement.scrollHeight-contentElement.scrollTop===contentElement.clientHeight;contentElement.classList.toggle("fade-top",!atTop);contentElement.classList.toggle("fade-bottom",!atBottom)}))}}